class Solution {
    public String explainRotatorCuffMuscles(String option) {
        String[] options = option.split(":");
        String[] actions = options[0].split(", ");
        String[] muscles = options[1].split(", ");

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < muscles.length; i++) {
