                sb.append(actions[2]); // medial rotation of the arm at the GH joint
                continue;
            } else if (muscles[i].equalsIgnoreCase("superspinatus")) {
                sb.append(actions[3]); // abduction beyond 15 degrees
                continue;
            } else if (muscles[i].equalsIgnoreCase("infraspinatus")) {
                sb.append(actions[4]); // lateral rotation of the arm at the GH joint
                continue;
            } else if (muscles[i].equalsIgnoreCase("teres major")) {
                sb.append(actions[5]); // lateral rotation of the arm at the GH joint
                continue;
            } else if (muscles[i].equalsIgnoreCase("teres minor")) {
                sb.append(actions[6]); // medial rotation of the arm at the GH joint
                continue;
            } else if (muscles[i].equalsIgnoreCase("infrapsinatus")) {
                sb.append(actions[7]); // lateral rotation of the arm at the GH joint
                continue;
            }
        }

        return sb.toString();
    }
}
